import React, { useState, useRef, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  X, Camera, User, Lock, Eye, EyeOff, Save, CheckCircle2,
  Phone, Building2, GraduationCap, Shield, Zap, Crown
} from 'lucide-react';

const ROLE_LABEL = {
  ETUDIANT: 'Étudiant',
  DELEGUE: 'Délégué',
  ADMIN: 'Administrateur',
  SUPER_ADMIN: 'Super Administrateur',
  PARENT: 'Parent',
  COMMERCIAL: 'Commercial',
};
const ROLE_COLOR = {
  ETUDIANT: '#22C55E',
  DELEGUE: '#38BDF8',
  ADMIN: '#F97316',
  SUPER_ADMIN: '#EF4444',
  PARENT: '#EC4899',
  COMMERCIAL: '#FBBF24',
};

/**
 * ProfileModal — modal de gestion du profil utilisateur.
 * Props:
 *   user        : objet utilisateur (nomComplet, numeroTelephone, role, universite, filiere, niveau, pointsIA, photoUrl)
 *   onClose     : fermer le modal
 *   onSaved     : callback(updatedUser) après sauvegarde réussie
 */
const ProfileModal = ({ user, onClose, onSaved }) => {
  const [tab, setTab] = useState('profil'); // 'profil' | 'securite'

  // — Profil
  const [nomComplet, setNomComplet]   = useState(user?.nomComplet || '');
  const [photoPreview, setPhotoPreview] = useState(user?.photoUrl || null);
  const [photoBase64, setPhotoBase64]   = useState(null); // nouveau fichier à envoyer
  const fileInputRef = useRef();

  // — Sécurité
  const [mdpActuel, setMdpActuel]     = useState('');
  const [mdpNouv, setMdpNouv]         = useState('');
  const [mdpConf, setMdpConf]         = useState('');
  const [showActuel, setShowActuel]   = useState(false);
  const [showNouv, setShowNouv]       = useState(false);
  const [showConf, setShowConf]       = useState(false);

  // — États globaux
  const [loading, setLoading]     = useState(false);
  const [success, setSuccess]     = useState('');
  const [erreur, setErreur]       = useState('');

  const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8080/api';
  const token  = localStorage.getItem('token');

  // ── Redimensionner l'image côté client avant upload ──────────────
  const resizeImage = useCallback((file) => {
    return new Promise((resolve) => {
      const MAX = 256;
      const reader = new FileReader();
      reader.onload = (e) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let w = img.width, h = img.height;
          if (w > h) { if (w > MAX) { h = h * MAX / w; w = MAX; } }
          else       { if (h > MAX) { w = w * MAX / h; h = MAX; } }
          canvas.width = w; canvas.height = h;
          canvas.getContext('2d').drawImage(img, 0, 0, w, h);
          resolve(canvas.toDataURL('image/jpeg', 0.82));
        };
        img.src = e.target.result;
      };
      reader.readAsDataURL(file);
    });
  }, []);

  const handlePhotoChange = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!file.type.startsWith('image/')) { setErreur('Fichier image uniquement (jpg, png…)'); return; }
    if (file.size > 5 * 1024 * 1024) { setErreur('Image trop lourde (max 5 Mo)'); return; }
    setErreur('');
    const b64 = await resizeImage(file);
    setPhotoBase64(b64);
    setPhotoPreview(b64);
  };

  // ── Sauvegarder le profil ─────────────────────────────────────────
  const sauvegarderProfil = async () => {
    setErreur(''); setSuccess('');
    if (!nomComplet.trim()) { setErreur('Le nom ne peut pas être vide'); return; }
    setLoading(true);
    try {
      const { default: axios } = await import('axios');
      const payload = { nomComplet: nomComplet.trim() };
      if (photoBase64 !== null) payload.photoUrl = photoBase64;
      const res = await axios.put(`${apiUrl}/utilisateurs/profil`, payload, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setSuccess('Profil mis à jour !');
      if (onSaved) onSaved({ ...user, nomComplet: nomComplet.trim(), photoUrl: photoBase64 ?? user?.photoUrl });
      setTimeout(() => setSuccess(''), 3000);
    } catch (e) {
      setErreur(e.response?.data?.error || 'Erreur lors de la sauvegarde');
    } finally { setLoading(false); }
  };

  // ── Changer le mot de passe ───────────────────────────────────────
  const changerMotDePasse = async () => {
    setErreur(''); setSuccess('');
    if (!mdpActuel) { setErreur('Saisissez votre mot de passe actuel'); return; }
    if (mdpNouv.length < 6) { setErreur('Le nouveau mot de passe doit faire au moins 6 caractères'); return; }
    if (mdpNouv !== mdpConf) { setErreur('Les deux nouveaux mots de passe ne correspondent pas'); return; }
    setLoading(true);
    try {
      const { default: axios } = await import('axios');
      await axios.put(`${apiUrl}/utilisateurs/mot-de-passe`, {
        motDePasseActuel: mdpActuel,
        nouveauMotDePasse: mdpNouv
      }, { headers: { Authorization: `Bearer ${token}` } });
      setSuccess('Mot de passe changé avec succès !');
      setMdpActuel(''); setMdpNouv(''); setMdpConf('');
      setTimeout(() => setSuccess(''), 4000);
    } catch (e) {
      setErreur(e.response?.data?.error || 'Erreur lors du changement de mot de passe');
    } finally { setLoading(false); }
  };

  const initiale   = (nomComplet || user?.nomComplet || '?').charAt(0).toUpperCase();
  const roleLabel  = ROLE_LABEL[user?.role] || user?.role || '';
  const roleColor  = ROLE_COLOR[user?.role] || '#94A3B8';
  const abonne     = user?.abonnementActif || user?.abonne;

  return (
    <motion.div
      initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
      style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', backdropFilter: 'blur(8px)',
        zIndex: 9000, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '16px' }}
      onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
    >
      <motion.div
        initial={{ scale: 0.93, opacity: 0, y: 20 }}
        animate={{ scale: 1, opacity: 1, y: 0 }}
        exit={{ scale: 0.93, opacity: 0, y: 20 }}
        transition={{ type: 'spring', stiffness: 400, damping: 30 }}
        style={{ background: 'white', border: '1px solid #e2e8f0',
          borderRadius: 24, width: '100%', maxWidth: 460, maxHeight: '90vh',
          overflow: 'hidden', display: 'flex', flexDirection: 'column',
          boxShadow: '0 16px 48px rgba(0,0,0,0.1)' }}
      >
        {/* Header */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          padding: '20px 24px 0', flexShrink: 0 }}>
          <h2 style={{ color: '#0f172a', fontWeight: 800, fontSize: '1.1rem', margin: 0 }}>Mon Profil</h2>
          <button onClick={onClose}
            style={{ background: '#f1f5f9', border: 'none', borderRadius: 10,
              width: 34, height: 34, display: 'flex', alignItems: 'center', justifyContent: 'center',
              cursor: 'pointer', color: '#475569' }}>
            <X size={17} />
          </button>
        </div>

        {/* Avatar + info */}
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', padding: '20px 24px 0' }}>
          <div style={{ position: 'relative', marginBottom: 14 }}>
            <div style={{ width: 88, height: 88, borderRadius: '50%', overflow: 'hidden',
              border: `3px solid ${roleColor}55`, background: '#f8fafc',
              display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              {photoPreview
                ? <img src={photoPreview} alt="avatar" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                : <span style={{ color: roleColor, fontWeight: 900, fontSize: '2rem' }}>{initiale}</span>
              }
            </div>
            <button onClick={() => fileInputRef.current?.click()}
              style={{ position: 'absolute', bottom: 0, right: 0, width: 28, height: 28,
                borderRadius: '50%', border: '2px solid rgba(10,15,28,0.98)',
                background: 'rgba(56,189,248,0.85)', cursor: 'pointer',
                display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <Camera size={13} color="#fff" />
            </button>
            <input ref={fileInputRef} type="file" accept="image/*" hidden onChange={handlePhotoChange} />
          </div>

          <p style={{ color: '#0f172a', fontWeight: 700, fontSize: '1rem', margin: '0 0 4px' }}>{user?.nomComplet}</p>
          <span style={{ padding: '3px 10px', borderRadius: 20, background: `${roleColor}22`,
            border: `1px solid ${roleColor}55`, color: roleColor, fontSize: '0.72rem', fontWeight: 700 }}>
            {roleLabel}
          </span>

          {/* Infos rapides */}
          <div style={{ display: 'flex', gap: 8, marginTop: 12, flexWrap: 'wrap', justifyContent: 'center' }}>
            {user?.universite?.nom && (
              <div style={{ display: 'flex', alignItems: 'center', gap: 4,
                padding: '4px 10px', borderRadius: 10, background: '#f8fafc',
                color: '#475569', fontSize: '0.72rem' }}>
                <Building2 size={11} /> {user.universite.nom}
              </div>
            )}
            {user?.filiere?.nom && (
              <div style={{ display: 'flex', alignItems: 'center', gap: 4,
                padding: '4px 10px', borderRadius: 10, background: '#f8fafc',
                color: '#475569', fontSize: '0.72rem' }}>
                <GraduationCap size={11} /> {user.filiere.nom}
              </div>
            )}
            {(user?.pointsIA != null) && (
              <div style={{ display: 'flex', alignItems: 'center', gap: 4,
                padding: '4px 10px', borderRadius: 10,
                background: abonne ? 'rgba(168,85,247,0.1)' : 'rgba(56,189,248,0.08)',
                color: abonne ? '#A855F7' : '#38BDF8', fontSize: '0.72rem', fontWeight: 700 }}>
                {abonne ? <Crown size={11} /> : <Zap size={11} />}
                {abonne ? 'PRO' : `${user.pointsIA} pts IA`}
              </div>
            )}
          </div>

          <p style={{ color: '#475569', fontSize: '0.73rem', margin: '8px 0 0',
            display: 'flex', alignItems: 'center', gap: 5 }}>
            <Phone size={11} /> {user?.numeroTelephone}
          </p>
        </div>

        {/* Tabs */}
        <div style={{ display: 'flex', gap: 6, padding: '16px 24px 0', flexShrink: 0 }}>
          {[['profil', <User size={13} />, 'Profil'], ['securite', <Lock size={13} />, 'Sécurité']].map(([key, icon, label]) => (
            <button key={key} onClick={() => { setTab(key); setErreur(''); setSuccess(''); }}
              style={{ flex: 1, padding: '8px', borderRadius: 10, border: 'none', cursor: 'pointer',
                fontWeight: 700, fontSize: '0.8rem', display: 'flex', alignItems: 'center',
                justifyContent: 'center', gap: 6, transition: 'all 0.2s',
                background: tab === key ? 'rgba(14,165,233,0.1)' : '#f1f5f9',
                color: tab === key ? '#38BDF8' : '#64748B',
                outline: tab === key ? '1px solid rgba(14,165,233,0.3)' : '1px solid #e2e8f0' }}>
              {icon}{label}
            </button>
          ))}
        </div>

        {/* Contenu scrollable */}
        <div style={{ overflowY: 'auto', padding: '16px 24px 24px', flex: 1 }}>

          <AnimatePresence mode="wait">
            {tab === 'profil' && (
              <motion.div key="profil"
                initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 10 }} transition={{ duration: 0.15 }}
              >
                <label style={{ color: '#475569', fontSize: '0.75rem', fontWeight: 700,
                  textTransform: 'uppercase', letterSpacing: '0.05em', display: 'block', marginBottom: 6 }}>
                  Nom complet
                </label>
                <div style={{ display: 'flex', alignItems: 'center', gap: 10,
                  background: '#f8fafc', border: '1px solid #e2e8f0',
                  borderRadius: 12, padding: '10px 14px', marginBottom: 8 }}>
                  <User size={15} color="#64748B" />
                  <input value={nomComplet} onChange={e => setNomComplet(e.target.value)}
                    placeholder="Votre nom complet"
                    style={{ background: 'none', border: 'none', outline: 'none',
                      color: '#0f172a', fontWeight: 600, fontSize: '0.9rem', flex: 1 }} />
                </div>

                <label style={{ color: '#475569', fontSize: '0.75rem', fontWeight: 700,
                  textTransform: 'uppercase', letterSpacing: '0.05em', display: 'block',
                  marginBottom: 6, marginTop: 14 }}>
                  Photo de profil
                </label>
                <button onClick={() => fileInputRef.current?.click()}
                  style={{ width: '100%', padding: '10px', borderRadius: 12,
                    border: '1px dashed rgba(56,189,248,0.3)', background: 'rgba(56,189,248,0.05)',
                    color: '#38BDF8', fontWeight: 600, fontSize: '0.82rem', cursor: 'pointer',
                    display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8 }}>
                  <Camera size={15} />
                  {photoPreview ? 'Changer la photo' : 'Choisir une photo'}
                </button>
                {photoPreview && (
                  <button onClick={() => { setPhotoPreview(null); setPhotoBase64(''); }}
                    style={{ width: '100%', padding: '8px', borderRadius: 10, marginTop: 6,
                      border: '1px solid rgba(239,68,68,0.3)', background: 'rgba(239,68,68,0.07)',
                      color: '#EF4444', fontWeight: 600, fontSize: '0.78rem', cursor: 'pointer' }}>
                    Supprimer la photo
                  </button>
                )}
              </motion.div>
            )}

            {tab === 'securite' && (
              <motion.div key="securite"
                initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -10 }} transition={{ duration: 0.15 }}
              >
                {[
                  { label: 'Mot de passe actuel', val: mdpActuel, set: setMdpActuel, show: showActuel, setShow: setShowActuel },
                  { label: 'Nouveau mot de passe', val: mdpNouv, set: setMdpNouv, show: showNouv, setShow: setShowNouv },
                  { label: 'Confirmer le nouveau', val: mdpConf, set: setMdpConf, show: showConf, setShow: setShowConf },
                ].map(({ label, val, set, show, setShow }) => (
                  <div key={label} style={{ marginBottom: 12 }}>
                    <label style={{ color: '#475569', fontSize: '0.75rem', fontWeight: 700,
                      textTransform: 'uppercase', letterSpacing: '0.05em',
                      display: 'block', marginBottom: 6 }}>
                      {label}
                    </label>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 10,
                      background: '#f8fafc', border: '1px solid #e2e8f0',
                      borderRadius: 12, padding: '10px 14px' }}>
                      <Lock size={15} color="#64748B" />
                      <input type={show ? 'text' : 'password'} value={val}
                        onChange={e => set(e.target.value)}
                        placeholder="••••••••"
                        style={{ background: 'none', border: 'none', outline: 'none',
                          color: '#0f172a', fontWeight: 600, fontSize: '0.9rem', flex: 1 }} />
                      <button onClick={() => setShow(v => !v)}
                        style={{ background: 'none', border: 'none', cursor: 'pointer',
                          color: '#475569', padding: 0 }}>
                        {show ? <EyeOff size={15} /> : <Eye size={15} />}
                      </button>
                    </div>
                  </div>
                ))}
                {mdpNouv && mdpNouv.length < 6 && (
                  <p style={{ color: '#F87171', fontSize: '0.75rem', margin: '4px 0 0' }}>
                    Au moins 6 caractères requis
                  </p>
                )}
              </motion.div>
            )}
          </AnimatePresence>

          {/* Messages feedback */}
          <AnimatePresence>
            {erreur && (
              <motion.div initial={{ opacity: 0, y: -4 }} animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0 }}
                style={{ marginTop: 12, padding: '10px 14px', borderRadius: 10,
                  background: 'rgba(239,68,68,0.12)', border: '1px solid rgba(239,68,68,0.3)',
                  color: '#FCA5A5', fontSize: '0.8rem', fontWeight: 600 }}>
                {erreur}
              </motion.div>
            )}
            {success && (
              <motion.div initial={{ opacity: 0, y: -4 }} animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0 }}
                style={{ marginTop: 12, padding: '10px 14px', borderRadius: 10,
                  background: 'rgba(34,197,94,0.12)', border: '1px solid rgba(34,197,94,0.3)',
                  color: '#86EFAC', fontSize: '0.8rem', fontWeight: 600,
                  display: 'flex', alignItems: 'center', gap: 6 }}>
                <CheckCircle2 size={14} /> {success}
              </motion.div>
            )}
          </AnimatePresence>

          {/* Bouton sauvegarder */}
          <button
            onClick={tab === 'profil' ? sauvegarderProfil : changerMotDePasse}
            disabled={loading}
            style={{ width: '100%', marginTop: 20, padding: '12px', borderRadius: 14,
              border: 'none', cursor: loading ? 'not-allowed' : 'pointer',
              background: 'linear-gradient(135deg, #38BDF8, #818CF8)',
              color: '#fff', fontWeight: 800, fontSize: '0.9rem',
              display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8,
              opacity: loading ? 0.7 : 1, transition: 'opacity 0.2s' }}>
            {loading ? '…' : <><Save size={15} /> {tab === 'profil' ? 'Sauvegarder le profil' : 'Changer le mot de passe'}</>}
          </button>
        </div>
      </motion.div>
    </motion.div>
  );
};

export default ProfileModal;
