import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { LogOut, X } from 'lucide-react';
import { clearSession } from '../utils/authSession';

/**
 * LogoutConfirmModal — modal de confirmation de déconnexion, partagé entre tous les dashboards.
 * Props:
 *   isOpen  : boolean
 *   onClose : fermer sans se déconnecter
 */
const LogoutConfirmModal = ({ isOpen, onClose }) => {
  const handleLogout = () => {
    clearSession();
    window.location.href = '/';
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          className="logout-modal-overlay"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
        >
          <motion.div
            className="logout-modal-box"
            initial={{ scale: 0.88, opacity: 0, y: 24 }}
            animate={{ scale: 1, opacity: 1, y: 0 }}
            exit={{ scale: 0.88, opacity: 0, y: 24 }}
            transition={{ type: 'spring', stiffness: 420, damping: 30 }}
          >
            {/* Icône */}
            <div className="logout-modal-icon">
              <LogOut size={28} color="#EF4444" />
            </div>

            {/* Texte */}
            <h3 className="logout-modal-title">Se déconnecter ?</h3>
            <p className="logout-modal-subtitle">
              Vous allez quitter votre session <strong style={{ color: '#0f172a' }}>RevisIA_H24</strong>.<br />
              Vos données sont sauvegardées automatiquement.
            </p>

            {/* Actions */}
            <div className="logout-modal-actions">
              <button className="btn-cancel-logout" onClick={onClose}>
                Rester connecté
              </button>
              <button className="btn-confirm-logout" onClick={handleLogout}>
                <LogOut size={15} />
                Déconnexion
              </button>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default LogoutConfirmModal;
