import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Headphones, Phone, X, ChevronDown } from 'lucide-react';

/**
 * AssistanceWidget — bouton flottant bas-droite affichant les numéros d'assistance.
 * Props:
 *   universiteId : Long optionnel — filtre les numéros par université
 */
const AssistanceWidget = ({ universiteId }) => {
  const [open, setOpen]         = useState(false);
  const [numeros, setNumeros]   = useState([]);
  const [loading, setLoading]   = useState(false);
  const panelRef                = useRef();

  const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8080/api';

  useEffect(() => {
    const fetchNumeros = async () => {
      setLoading(true);
      try {
        const { default: axios } = await import('axios');
        const url = universiteId
          ? `${apiUrl}/assistance?universiteId=${universiteId}`
          : `${apiUrl}/assistance`;
        const res = await axios.get(url);
        setNumeros(res.data || []);
      } catch { /* silencieux si pas de numéros configurés */ }
      finally { setLoading(false); }
    };
    fetchNumeros();
  }, [apiUrl, universiteId]);

  // Fermer en cliquant dehors
  useEffect(() => {
    const handler = (e) => {
      if (panelRef.current && !panelRef.current.contains(e.target)) setOpen(false);
    };
    if (open) document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [open]);

  // Ne rien afficher s'il n'y a aucun numéro configuré
  if (!loading && numeros.length === 0) return null;

  return (
    <div ref={panelRef}
      style={{
        position: 'fixed',
        bottom: window.innerWidth < 768 ? 'calc(68px + env(safe-area-inset-bottom, 0px))' : '24px',
        right: 16,
        zIndex: 8000
      }}
    >
      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ opacity: 0, y: 12, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 12, scale: 0.95 }}
            transition={{ type: 'spring', stiffness: 400, damping: 30 }}
            style={{ position: 'absolute', bottom: 58, right: 0,
              width: 280, background: 'white',
              border: '1px solid #e2e8f0', borderRadius: 18,
              boxShadow: '0 12px 40px rgba(0,0,0,0.1)',
              overflow: 'hidden' }}
          >
            {/* Entête */}
            <div style={{ padding: '14px 16px 10px',
              borderBottom: '1px solid #e2e8f0',
              display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                <div style={{ width: 30, height: 30, borderRadius: 10,
                  background: 'linear-gradient(135deg, #22C55E, #16A34A)',
                  display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <Headphones size={15} color="#fff" />
                </div>
                <div>
                  <p style={{ color: '#0f172a', fontWeight: 800, fontSize: '0.85rem', margin: 0 }}>
                    Assistance
                  </p>
                  <p style={{ color: '#475569', fontSize: '0.7rem', margin: 0 }}>
                    {numeros.length} numéro{numeros.length > 1 ? 's' : ''} disponible{numeros.length > 1 ? 's' : ''}
                  </p>
                </div>
              </div>
              <button onClick={() => setOpen(false)}
                style={{ background: '#f1f5f9', border: '1px solid #e2e8f0', borderRadius: 8,
                  width: 28, height: 28, display: 'flex', alignItems: 'center', justifyContent: 'center',
                  cursor: 'pointer', color: '#475569' }}>
                <X size={14} />
              </button>
            </div>

            {/* Liste des numéros */}
            <div style={{ padding: '10px 12px 14px', display: 'flex', flexDirection: 'column', gap: 8 }}>
              {numeros.map((n) => (
                <a key={n.id} href={`tel:${n.numero.replace(/\s/g, '')}`}
                  style={{ display: 'flex', alignItems: 'center', gap: 12,
                    padding: '10px 12px', borderRadius: 12,
                    background: 'rgba(34,197,94,0.07)',
                    border: '1px solid rgba(34,197,94,0.15)',
                    textDecoration: 'none', transition: 'background 0.2s' }}
                  onMouseEnter={e => e.currentTarget.style.background = 'rgba(34,197,94,0.15)'}
                  onMouseLeave={e => e.currentTarget.style.background = 'rgba(34,197,94,0.07)'}
                >
                  <div style={{ width: 34, height: 34, borderRadius: 10, flexShrink: 0,
                    background: 'rgba(34,197,94,0.15)',
                    display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                    <Phone size={15} color="#22C55E" />
                  </div>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <p style={{ color: '#0f172a', fontWeight: 700, fontSize: '0.82rem',
                      margin: 0, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                      {n.nom}
                    </p>
                    <p style={{ color: '#22C55E', fontWeight: 800, fontSize: '0.9rem', margin: 0 }}>
                      {n.numero}
                    </p>
                    {n.description && (
                      <p style={{ color: '#475569', fontSize: '0.68rem', margin: 0, marginTop: 1 }}>
                        {n.description}
                      </p>
                    )}
                  </div>
                </a>
              ))}
            </div>

            {/* Footer */}
            <div style={{ padding: '8px 16px 12px', borderTop: '1px solid #e2e8f0',
              textAlign: 'center' }}>
              <p style={{ color: '#475569', fontSize: '0.68rem', margin: 0 }}>
                Cliquez sur un numéro pour appeler directement
              </p>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Bouton flottant */}
      <motion.button
        onClick={() => setOpen(v => !v)}
        whileHover={{ scale: 1.08 }}
        whileTap={{ scale: 0.93 }}
        animate={open ? {} : {
          boxShadow: ['0 0 0 0 rgba(34,197,94,0.4)', '0 0 0 10px rgba(34,197,94,0)', '0 0 0 0 rgba(34,197,94,0)']
        }}
        transition={open ? {} : { duration: 2.5, repeat: Infinity }}
        style={{ width: 48, height: 48, borderRadius: '50%', border: 'none', cursor: 'pointer',
          background: open
            ? 'rgba(100,116,139,0.6)'
            : 'linear-gradient(135deg, #22C55E, #16A34A)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          boxShadow: open ? 'none' : '0 4px 20px rgba(34,197,94,0.4)',
          transition: 'background 0.2s' }}
      >
        {open ? <ChevronDown size={20} color="#fff" /> : <Headphones size={20} color="#fff" />}
      </motion.button>
    </div>
  );
};

export default AssistanceWidget;
